mapper.select:
SELECT a.IDX, b.AREABESTNAME, c.AREANAME, d.SITENAME, e.COMMENT AS ACTIONNAME, a.MSGSPD, a.MSGDELAY, a.MODX, a.MODY, f.COMMENT AS COLORNAME, a.TYPE, a.MSG, a.IMGPATH, a.SUCCESS, a.SENDDATE, a.ENDDATE FROM SB_MESSAGE AS a LEFT JOIN SB_AREABINFO AS b ON a.AREABESTID = b.AREABESTID LEFT JOIN SB_AREAINFO AS c ON a.AREAID = c.AREAID LEFT JOIN SB_SIGNINFO AS d ON a.SITEID = d.SITEID LEFT JOIN SB_SIGNACTION AS e ON a.MSGACTION = e.NUM AND e.TYPE = 1 LEFT JOIN SB_SIGNACTION AS f ON a.MSGCOLOR = f.NUM AND f.TYPE = 4 WHERE a.DIVISION IN (1, 2) AND a.SUCCESS IN (1, 2, 3) AND a.ENDDATE > NOW()
AND a.AREABESTID = #{areabestid}
AND a.AREAID = #{areaid}
AND a.SITEID = #{siteid}
ORDER BY a.AREABESTID, a.AREAID, a.SITEID

SELECT a.IDX, b.AREABESTNAME, c.AREANAME, d.SITENAME, e.COMMENT AS ACTIONNAME, a.MSGSPD, a.MSGDELAY, a.MODX, a.MODY, f.COMMENT AS COLORNAME, a.TYPE, a.MSG, a.IMGPATH, a.SUCCESS, a.ORDERNUM, a.SENDDATE, a.REF_NAME FROM SB_MESSAGE AS a LEFT JOIN SB_AREABINFO AS b ON a.AREABESTID = b.AREABESTID LEFT JOIN SB_AREAINFO AS c ON a.AREAID = c.AREAID LEFT JOIN SB_SIGNINFO AS d ON a.SITEID = d.SITEID LEFT JOIN SB_SIGNACTION AS e ON a.MSGACTION = e.NUM AND e.TYPE = 1 LEFT JOIN SB_SIGNACTION AS f ON a.MSGCOLOR = f.NUM AND f.TYPE = 4 WHERE a.DIVISION = 0
AND a.SUCCESS IN (1, 2, 3)
AND a.SUCCESS IN (0, 1, 2, 3)
AND a.AREABESTID = #{areabestid}
AND a.AREAID = #{areaid}
AND a.SITEID = #{siteid}
ORDER BY a.AREABESTID, a.AREAID, a.SITEID, a.ORDERNUM


 SELECT AREAID , SITEID, SITENAME, AREA_CODE, MODX, MODY
	FROM SB_SIGNINFO
	WHERE 1 = 1

		AND a.AREABESTID = #{areabestid}


		AND a.AREAID = #{areaid}


		AND a.SITEID = #{siteid}

	ORDER BY SITEID


SELECT AREABESTID, AREAID, SITEID, MODX, MODY, SITENAME
	FROM SB_SIGNINFO
	WHERE SITEID = #{siteid}


SELECT IDX, MSGCOLOR, MSGACTION, MSGSPD, MSGDELAY, TYPE, MSG, IMGMSG, IMGPATH, TM
	 FROM SB_MESSAGELIST
 	 WHERE IDX = #{idx}

mapper.update:

UPDATE SB_MESSAGELIST SET
	MSGCOLOR = #{msgcolor}, MSGACTION = #{msgaction},
	ORDERNUM = '0', MSGSPD = #{msgspd}, MSGDELAY = #{msgdelay},
	MODX = #{modx}, MODY = #{mody}, TYPE = #{type}, 
	MSG = #{msg}, IMGMSG = #{imgmsg}, IMGPATH = #{imgpath}
	, SAVEIMG = #{saveimg}
	WHERE IDX = #{idx}


UPDATE SB_SIGNINFO SET AREABESTID = #{areabestid}, AREAID = #{areaid}, SITENAME = #{sitename}, 
	SYSTYPE = #{systype}, CONTYPE = #{contype}, PORT = #{port}, BAUDRATE = #{baudrate}, 
	GATEWAY = #{gateway}, NETMASK = #{netmask}, MODX = #{modx}, MODY = #{mody}, 
	URGACTION = #{urgaction}, URGSPD = #{urgspd}, URGDELAY = #{urgdelay}, 
	URGHOUR = #{urghour}, URGMIN = #{urgmin}, POINTX = #{pointx}, POINTY = #{pointy}

WHERE SITEID = #{siteid}

mapper.select:

 SELECT a.IDX, a.DIVISION, b.AREABESTNAME, c.AREANAME, d.SITENAME, a.USERID,
	a.TYPE, a.MSG, a.IMGPATH, a.SUCCESS, a.SENDDATE
	FROM SB_MESSAGELOG AS a
	LEFT JOIN SB_AREABINFO AS b ON a.AREABESTID = b.AREABESTID
	LEFT JOIN SB_AREAINFO AS c ON a.AREAID = c.AREAID
	LEFT JOIN SB_SIGNINFO AS d ON a.SITEID = d.SITEID
	WHERE a.SENDDATE BETWEEN #{sdate} AND #{edate}


		AND a.AREABESTID = #{areabestid}


		AND a.AREAID = #{areaid}


		AND a.SITEID = #{siteid}

	ORDER BY a.SENDDATE DESC
